// HandIcons — brandové hand-drawn ikonky ako inline SVG.
//
// PREČO INLINE a nie <img src="…svg">: ikonka musí prebrať farbu textu (`currentColor`),
// inak by v zlatej pilulke svietila čierna kresba. Ako <img> sa ofarbiť nedá.
//
// PREČO GENEROVANÉ a nie ručne prepísané: zdroj je `vstupy/vizualna-identita/Icons hand drawn/`
// (zrkadlené do `vystupy/dashboard/embeds/brand/icons-handdrawn/`). Pri výmene ikonky prepíš
// SVG v zdroji a pregeneruj — needituj `d` tu. Zo súborov sa odstraňuje `fill="#000000"`,
// aby ho nahradil `currentColor`.
//
// Rozmer sa riadi CSS-om (`width`/`height` z props), nie viewBoxom — pôvodné súbory majú
// 800×800 a bez tohto by roztrhali layout.
import type { CSSProperties } from 'react';

export interface HandIconProps {
  size?: number;
  className?: string;
  style?: CSSProperties;
  /** Dekoratívne ikonky nechaj bez `title`; keď ikonka nesie význam sama, doplň ho. */
  title?: string;
}

function svgProps(size: number) {
  return {
    width: size,
    height: size,
    fill: 'currentColor',
    focusable: false as const,
    'aria-hidden': true as const,
  };
}

